const spreadsheetId = "YOUR_SPREADSHEET_ID",
  sheetName = "Sheet1";
return [{ json: { spreadsheetId, sheetName, range: "'" + sheetName.replace(/'/g, "''") + "'" } }];

function keywordSheetInput({ values }) {
  if (!Array.isArray(values)) throw new Error("Expected the complete keyword worksheet values");
  if (values.length === 0) return { rows: [], count: 0 };
  if (!Array.isArray(values[0])) throw new Error("The keyword worksheet needs a header row");
  const headers = values[0];
  for (const name of ["Number", "Keyword", "Service?"])
    if (headers.filter((value) => value === name).length !== 1)
      throw new Error("The first worksheet row must contain exactly one " + name + " header");
  const rows = [];
  for (let rowIndex = 1; rowIndex < values.length; rowIndex++) {
    const cells = values[rowIndex];
    if (!Array.isArray(cells)) throw new Error("Invalid keyword worksheet row " + (rowIndex + 1));
    if (!cells.some((value) => value !== null && value !== undefined && value !== "")) continue;
    const row = Object.create(null);
    for (let column = 0; column < cells.length; column++) {
      const header = headers[column] || "col_" + column;
      if (!["string", "number", "boolean"].includes(typeof header))
        throw new Error("Invalid keyword worksheet header");
      row[String(header)] = cells[column] ?? "";
    }
    const number = row.Number,
      keyword = row.Keyword;
    if (
      !["string", "number", "boolean"].includes(typeof number) ||
      (typeof number === "string" && !number.trim()) ||
      (typeof number === "number" && !Number.isFinite(number))
    )
      throw new Error("Keyword row " + (rowIndex + 1) + " needs a Number match key");
    if (
      !["string", "number", "boolean"].includes(typeof keyword) ||
      (typeof keyword === "string" && !keyword.trim()) ||
      (typeof keyword === "number" && !Number.isFinite(keyword))
    )
      throw new Error("Keyword row " + (rowIndex + 1) + " needs a nonblank scalar Keyword");
    rows.push({ index: rows.length, number, keyword: String(keyword), row });
  }
  return { rows, count: rows.length };
}

const result = keywordSheetInput({ values: $input.first().json.body.values ?? [] });
return result.rows.map((row, index) => ({ json: row, pairedItem: { item: 0 } }));

const batch = $("Process Keywords in Batches")
    .all(1, $runIndex)
    .map((item) => item.json),
  items = $input.all();
if (items.length !== batch.length) throw new Error("Missing keyword batch classifications");
const results = items.map((item, index) => {
  const classification = item.json.output?.Isservice;
  if (!["yes", "no"].includes(classification))
    throw new Error(
      "Classifier must return Isservice as yes or no; this batch has not been written",
    );
  return { ...batch[index], classification };
});
return [{ json: { results, start: batch[0].index, count: results.length } }];

function keywordWritePlan({ values, results, sheetName, start }) {
  if (!Array.isArray(values) || !Array.isArray(values[0]))
    throw new Error("The current keyword worksheet has no header row");
  if (!Array.isArray(results) || results.length < 1 || results.length > 6)
    throw new Error("Expected a complete classified batch");
  if (typeof sheetName !== "string" || !sheetName.trim())
    throw new Error("Configure the keyword worksheet name");
  const headers = values[0],
    key = headers.indexOf("Number"),
    target = headers.indexOf("Service?");
  if (key < 0 || target < 0) throw new Error("The worksheet needs Number and Service? headers");
  const column = (index) => {
    let label = "";
    for (let n = index + 1; n; n = Math.floor((n - 1) / 26))
      label = String.fromCharCode(65 + ((n - 1) % 26)) + label;
    return label;
  };
  const tab = "'" + sheetName.replace(/'/g, "''") + "'",
    data = [],
    unmatched = [];
  for (const result of results) {
    if (
      !result ||
      !Number.isInteger(result.index) ||
      !["string", "number", "boolean"].includes(typeof result.number) ||
      !["yes", "no"].includes(result.classification)
    )
      throw new Error("Invalid keyword classification or match key");
    const row = values.findIndex(
      (cells, index) =>
        index > 0 &&
        Array.isArray(cells) &&
        cells[key] !== null &&
        cells[key] !== undefined &&
        String(cells[key]) === String(result.number),
    );
    if (row < 0) unmatched.push(result.index);
    else
      data.push({
        range: tab + "!" + column(target) + (row + 1),
        values: [[result.classification]],
      });
  }
  return {
    data,
    hasUpdates: data.length > 0,
    expectedCells: data.length,
    unmatched,
    results,
    start,
    count: results.length,
  };
}

const batch = $("Keep complete batch classifications").first(0, $runIndex).json;
return [
  {
    json: keywordWritePlan({
      values: $input.first().json.body.values ?? [],
      results: batch.results,
      start: batch.start,
      sheetName: $("Choose the keyword worksheet").first().json.sheetName,
    }),
  },
];

function keywordWriteReceipt({ results, start, count, expectedCells, unmatched, actualCells }) {
  if (
    !Array.isArray(results) ||
    results.length !== count ||
    !Number.isInteger(start) ||
    !Number.isInteger(count) ||
    count < 1 ||
    count > 6 ||
    !Array.isArray(unmatched) ||
    !Number.isInteger(expectedCells) ||
    expectedCells !== count - unmatched.length
  )
    throw new Error("Invalid keyword batch write plan");
  if (expectedCells > 0 && actualCells !== expectedCells)
    throw new Error(
      "Google Sheets did not confirm every planned Service? cell; check the worksheet before replaying this batch",
    );
  return { results, start, count, updated: expectedCells, unmatched };
}

const plan = $("Plan only matching Service cells").first(0, $runIndex).json;
return [
  {
    json: keywordWriteReceipt({
      ...plan,
      actualCells: plan.hasUpdates ? $input.first().json.body.totalUpdatedCells : null,
    }),
  },
];

const batches = $input.all().map((item) => item.json);
return [
  {
    json: {
      results: batches.flatMap((batch) => batch.results),
      batches: batches.map(({ start, count, updated, unmatched }) => ({
        start,
        count,
        updated,
        unmatched,
      })),
      count: batches.reduce((sum, batch) => sum + batch.count, 0),
    },
  },
];
